    if let Some(o) = &closing.onto {
        return Ok(o.clone());
    }
    let opening = format!("heads(::({tip}) & description(regex:\"^[^\\n]* opening(\\n|$)\"))");
    let likely = jj::local_bookmarks_at(repo, &format!("heads(::(({opening})-) & bookmarks())"))?;
